DROP TABLE IF EXISTS `world`.`mystic_spawn`;
CREATE TABLE `world`.`mystic_spawn` (
  `id` int unsigned NOT NULL AUTO_INCREMENT, `entry` int unsigned NOT NULL, `map` smallint unsigned NOT NULL,
